__NUXT_JSONP__("/contact/thanks", {data:[{details:{slug:"en",pageTitle:"Thanks for contacting MLI | Mentor Language Institute",pageDescription:"Thank you for your inquiry to Mentor Language Institute.",title:"Thanks for contacting MLI",subtitle:["Thank you for your inquiry to Mentor Language Institute.\u003Cbr \u002F\u003EAn admission staff member will respond to you shortly.","The process for studying abroad in the United States is very complicated so we are here to guide you through your needs over the phone.","If you did not check \"Do not contact me by phone\",  we will call you in a day or two to follow up.","Thank you!"],dir:"\u002Fcontact-thanks",path:"\u002Fcontact-thanks\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:28.992Z",updatedAt:"2025-05-26T12:06:27.723Z"}}],fetch:{},mutations:void 0});